import fontkit from "@pdf-lib/fontkit";
import { PDFDocument, rgb, type PDFFont, type PDFPage } from "pdf-lib";
import { formatDateTime } from "@/lib/dates";
import { FONTS, readAsset } from "./templates";

/**
 * « Preuve de signature » (step 8): a one-page PDF generated by Binivol that
 * sums up, for the three signed documents, who signed, when, how the signer
 * was identified, from which browser, and the SHA-256 of each final PDF.
 * Stored with the UL copy (document kind OTHER).
 */

export interface ProofSigner {
  role: string;
  name: string;
  quality: string | null;
  signedAt: Date;
  method: string;
  /** « e-mail vérifié : … » or « vérifiée en présence par … ». */
  verification: string;
  input: string;
  userAgent: string | null;
  ipHash: string | null;
}

export interface ProofInput {
  structure: string;
  personRef: string;
  personName: string;
  generatedAt: Date;
  signers: ProofSigner[];
  files: { fileName: string; sha256: string }[];
}

const MARGIN = 48;
const INK = rgb(0.08, 0.08, 0.1);
const MUTED = rgb(0.35, 0.35, 0.4);

/** Splits a text in lines no wider than `width` (words, then characters for long tokens). */
export function wrap(text: string, width: number, measure: (t: string) => number): string[] {
  const lines: string[] = [];
  let line = "";
  for (const word of text.split(/\s+/).filter(Boolean)) {
    const candidate = line ? `${line} ${word}` : word;
    if (measure(candidate) <= width) {
      line = candidate;
      continue;
    }
    if (line) lines.push(line);
    let rest = word;
    while (measure(rest) > width) {
      let cut = rest.length;
      while (cut > 1 && measure(rest.slice(0, cut)) > width) cut--;
      lines.push(rest.slice(0, cut));
      rest = rest.slice(cut);
    }
    line = rest;
  }
  if (line) lines.push(line);
  return lines;
}

class Writer {
  y: number;
  constructor(
    readonly page: PDFPage,
    readonly font: PDFFont,
  ) {
    this.y = page.getSize().height - MARGIN;
  }
  get width() {
    return this.page.getSize().width - 2 * MARGIN;
  }
  text(value: string, size = 9, color = INK, indent = 0) {
    for (const line of wrap(value, this.width - indent, (t) =>
      this.font.widthOfTextAtSize(t, size),
    )) {
      this.page.drawText(line, { x: MARGIN + indent, y: this.y, size, font: this.font, color });
      this.y -= size * 1.35;
    }
  }
  gap(points = 6) {
    this.y -= points;
  }
  rule() {
    this.page.drawLine({
      start: { x: MARGIN, y: this.y + 4 },
      end: { x: MARGIN + this.width, y: this.y + 4 },
      thickness: 0.5,
      color: MUTED,
    });
    this.y -= 6;
  }
}

export async function buildProofPdf(input: ProofInput): Promise<Uint8Array> {
  const doc = await PDFDocument.create();
  doc.registerFontkit(fontkit);
  const font = await doc.embedFont(await readAsset(FONTS.TEXT), { subset: true });
  const page = doc.addPage([595.28, 841.89]);
  const w = new Writer(page, font);

  w.text("Preuve de signature électronique", 16);
  w.text(`${input.structure} · Croix-Rouge française`, 10, MUTED);
  w.gap(4);
  w.text(`Dossier de ${input.personName} (${input.personRef})`, 10);
  w.text(`Générée par Binivol le ${formatDateTime(input.generatedAt)} (heure de Paris).`, 8, MUTED);
  w.gap(8);

  w.text("Signataires", 11);
  w.rule();
  for (const signer of input.signers) {
    w.text(`${signer.role} : ${signer.name}${signer.quality ? ` (${signer.quality})` : ""}`, 9.5);
    w.text(
      `Signé le ${formatDateTime(signer.signedAt)} (heure de Paris), signature ${signer.input.toLowerCase()}.`,
      8.5,
      INK,
      10,
    );
    w.text(`Identification : ${signer.method}, ${signer.verification}.`, 8.5, INK, 10);
    if (signer.userAgent) w.text(`Navigateur : ${signer.userAgent}`, 7.5, MUTED, 10);
    if (signer.ipHash)
      w.text(`Empreinte de l'adresse IP (HMAC-SHA-256) : ${signer.ipHash}`, 7.5, MUTED, 10);
    w.gap(4);
  }

  w.gap(4);
  w.text("Documents signés (empreintes SHA-256 des fichiers finaux)", 11);
  w.rule();
  for (const document of input.files) {
    w.text(document.fileName, 9);
    w.text(document.sha256, 8, MUTED, 10);
    w.gap(2);
  }

  w.gap(8);
  w.text("Valeur de cette signature", 11);
  w.rule();
  w.text(
    "Signature électronique simple au sens du règlement (UE) n° 910/2014 (eIDAS, article 25). Sa valeur repose sur un faisceau de preuves : l'identification de chaque signataire (code à usage unique reçu sur son adresse e-mail, ou vérification d'identité en présence d'un responsable), l'horodatage du serveur, le navigateur utilisé, une empreinte de l'adresse IP, et l'empreinte SHA-256 de chaque document final, aplati et non modifiable. Toute modification d'un document change son empreinte.",
    8.5,
  );
  w.gap(4);
  w.text(
    "Ce n'est ni une signature avancée ni une signature qualifiée : aucun certificat n'est délivré au signataire. En cas de contestation, la charge de la preuve revient à la Croix-Rouge française, qui conserve ce document avec la copie de l'unité locale.",
    8.5,
    MUTED,
  );

  doc.setTitle("Preuve de signature");
  doc.setProducer("Binivol");
  doc.setCreator("Binivol");
  return doc.save({ useObjectStreams: false });
}
